import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { uv, mix, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Color } = ctx.THREE;
  const group = new Group();

  // 1. Core Visual Definitions
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. Base Plate (Engineered Gradient Surface with Aspect Ratio 1.6 from Atlas Region)
  const plateGeo = new PlaneGeometry(3.2, 2.0);

  // Custom TSL-driven background material for high quality depth and grain mapping
  const plateMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95
  });

  const colorSurface = uniform(new Color(palette.surface));
  const colorInk = uniform(new Color(palette.ink));

  // Vertical engineered gradient using TSL
  const gradientNode = mix(colorSurface, colorInk, uv().y);
  plateMat.colorNode = gradientNode;

  const plateMesh = new Mesh(plateGeo, plateMat);
  group.add(plateMesh);

  // Subtle Border Plate to accent the frame (Machined metal look)
  const borderGeo = new PlaneGeometry(3.24, 2.04);
  const borderMat = new MeshBasicNodeMaterial({
    color: palette.accent,
    transparent: true,
    opacity: 0.4
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // Load ceramic grain map if available
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      plateMat.map = tex;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // 3. Text & Layout Injection (Lora display typeface simulated via atlas)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryText = items.find(item => item.role === 'headline' || item.text === 'Features')?.text ?? 'Features';

  const textObj = ctx.fontAtlas.createText(primaryText, {
    fontSize: 0.38,
    color: palette.paper,
    align: 'center'
  });
  textObj.position.set(0, 0.05, 0.05);
  group.add(textObj);

  // High premium signal accent bar underneath
  const accentGeo = new PlaneGeometry(0.3, 0.03);
  const accentMat = new MeshBasicNodeMaterial({ color: palette.accent });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -0.4, 0.06);
  group.add(accentMesh);

  // Decorative Mono tag representing high precision
  const tagObj = ctx.fontAtlas.createText('ATELIER DEPT / MODULE 02', {
    fontSize: 0.07,
    color: palette.accent,
    align: 'center'
  });
  tagObj.position.set(0, 0.6, 0.05);
  group.add(tagObj);

  // 4. Sprite Billboarding Controller (Matches camera orientation smoothly)
  const onTick = () => {
    const scene = group.parent;
    if (!scene) return;
    let camera = null;
    scene.traverse((obj) => {
      if (obj.isCamera) camera = obj;
    });
    if (camera) {
      group.quaternion.copy(camera.quaternion);
    }
  };
  gsap.ticker.add(onTick);

  // 5. Entrance Animation (Rise-in + Settle)
  const entranceTl = gsap.timeline();
  group.position.y -= 0.3;
  group.scale.set(0.9, 0.9, 0.9);

  entranceTl.to(group.position, {
    y: '+=0.3',
    duration: 0.9,
    ease: 'power3.out'
  });
  entranceTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.1,
    ease: 'elastic.out(1.0, 0.75)'
  }, 0);

  // Apply visual primitives (none requested, but support future attachments)
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const pInstance = ctx.primitives[prim.name](group, prim.params);
        if (pInstance && pInstance.cleanup) {
          primitiveCleanups.push(pInstance.cleanup);
        }
      }
    });
  }

  // 6. Cleanup Hook
  group.userData = {
    handlers: {},
    cleanup: () => {
      gsap.ticker.remove(onTick);
      entranceTl.kill();
      primitiveCleanups.forEach(fn => fn());
      plateGeo.dispose();
      plateMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      accentGeo.dispose();
      accentMat.dispose();
    }
  };

  return group;
}
